package com.codeguardian.config;
import com.codeguardian.entity.User; import com.codeguardian.repository.UserRepository; import lombok.RequiredArgsConstructor; import org.springframework.boot.CommandLineRunner; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.stereotype.Component; import java.time.LocalDateTime;
@Component @RequiredArgsConstructor public class DataInitializer implements CommandLineRunner { private final UserRepository users; private final BCryptPasswordEncoder encoder; public void run(String... args){if(users.findByUsername("admin").isEmpty()) users.save(User.builder().username("admin").email("admin@codeguardian.ai").passwordHash(encoder.encode("admin123")).realName("System Administrator").status("ACTIVE").createdAt(LocalDateTime.now()).build());} }
